<script setup>
/**
 * example-map.vue — Application Profile: Example Map
 *
 * Starter profile — copy this file to create a new map profile.
 * Filename = profile name in the profile-config prop.
 *
 * Shadow DOM notes:
 * - Mapbox cannot find elements by string ID inside a Shadow DOM.
 *   Always use a Vue template ref and pass the element directly.
 * - <style scoped> blocks are silently dropped by Vue's defineCustomElement
 *   for async-loaded child components. useShadowStyles() injects them correctly.
 *
 * Usage:
 *   <doxa-map profile-config='{"profile":"example-map","tk":"pk.eyJ..."}'></doxa-map>
 */

import { inject, onMounted, onBeforeUnmount, ref } from 'vue'
import { useMapInstance }   from '../composables/useMapInstance.js'
import { useShadowStyles }  from '../composables/useShadowStyles.js'

// ─── Read config provided by ProfileLoader ───────────────────────────────────

const mapboxToken = inject('mapboxToken')

// ─── Template ref — actual DOM element passed to Mapbox ──────────────────────

const mapContainer = ref(null)

// ─── Map instance ─────────────────────────────────────────────────────────────

const { map, isMapReady, initializeMap, destroy } = useMapInstance({
  containerRef: mapContainer,
  accessToken:  mapboxToken.value,
  style:        'mapbox://styles/mapbox/light-v11',
  center:       [20, 10],
  zoom:         1.8
})

// ─── Inject component styles into shadow root ─────────────────────────────────
// Required because defineAsyncComponent drops <style scoped> in Shadow DOM.

useShadowStyles(`
  .example-map {
    width: 100%;
    height: 100%;
    position: relative;
  }
  .map-canvas {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
  }
  .map-loading {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #f5f5f5;
    font-family: sans-serif;
    color: #666;
    z-index: 1;
  }
`, 'example-map')

// ─── Lifecycle ────────────────────────────────────────────────────────────────

onMounted(()       => initializeMap())
onBeforeUnmount(() => destroy())
</script>

<template>
  <div class="example-map">
    <div v-if="!isMapReady" class="map-loading">Loading map…</div>
    <div ref="mapContainer" class="map-canvas" />
  </div>
</template>
