<script setup>
/**
 * world-map.vue — Suite: World Overview Map (Suite #2)
 *
 * Second suite to prove two independent suites running in two shadow DOMs.
 * Different style and center from example-map.
 *
 * WordPress usage:
 *   <doxa-map suite-config='{"suite":"world-map","tk":"pk.eyJ..."}'></doxa-map>
 */

import { inject, onMounted, onBeforeUnmount, ref } from 'vue'
import { useMapInstance } from '../composables/useMapInstance.js'

const mapboxToken = inject('mapboxToken')
const mapContainer = ref(null)

const { map, isMapReady, initializeMap, destroy } = useMapInstance({
  containerRef: mapContainer,
  accessToken:  mapboxToken.value,
  style:        'mapbox://styles/mapbox/dark-v11',
  center:       [105, 20],   // centered on Asia
  zoom:         2.2
})

onMounted(()        => initializeMap())
onBeforeUnmount(()  => destroy())
</script>

<template>
  <div class="world-suite">
    <div v-if="!isMapReady" class="map-loading">Loading world map…</div>
    <div ref="mapContainer" class="map-container" />
  </div>
</template>

<style scoped>
.world-suite {
  width: 100%;
  height: 100%;
  position: relative;
}
.map-container {
  width: 100%;
  height: 100%;
}
.map-loading {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1a1a2e;
  font-family: sans-serif;
  color: #aaa;
  z-index: 1;
}
</style>
